const Component = ({ item }) => {
const frame=useCurrentFrame(); const p=item.props;
const cards=JSON.parse(p.cards);const stages=JSON.parse(p.stages);const labels=JSON.parse(p.labels);
const card=cards.find(c=>frame>=c.start&&frame<c.end);
const stage=stages.find(c=>frame>=c.start&&frame<c.end);
const label=labels.find(c=>frame>=c.start&&frame<c.end);
const original=frame<1118;const ref=frame>=1118&&frame<1424;
const rootStyle={position:"absolute",inset:0,backgroundColor:"transparent",fontFamily:p.font};
const barStyle={position:"absolute",left:0,top:0,width:576,height:original?48:60,backgroundColor:original?p.black:p.yellow,color:original?p.white:p.black,display:"flex",alignItems:"center",justifyContent:"center",fontSize:24};
const labelStyle={position:"absolute",left:24,top:64,width:528,height:36,display:"flex",alignItems:"center",justifyContent:"center",fontSize:24,color:p.black};
const plateStyle={position:"absolute",left:0,top:800,width:576,height:224,backgroundColor:p.black};
const captionStyle={position:"absolute",left:24,top:824,width:528,height:168,display:"flex",alignItems:"center",justifyContent:"center",textAlign:"center",fontSize:28,lineHeight:"38px",whiteSpace:"pre-wrap",color:p.white,textShadow:"none"};
const refStyle={position:"absolute",left:24,top:270,width:256,height:199.111111,overflow:"hidden"};
const imgStyle={position:"absolute",left:-7.585185,top:-85.333333,width:273.066667,height:485.451852,maxWidth:"none"};
return <div style={rootStyle}><div style={barStyle}>{stage?stage.text:""}</div>{label&&<div style={labelStyle}>{label.text}</div>}{ref&&p.reference&&<div style={refStyle}><Img src={p.reference} style={imgStyle}/></div>}{!original&&<div style={plateStyle}/ >}{card&&<div style={captionStyle}>{card.text}</div>}</div>;
};
